Object.assign(SNIP,{});PRESET_NOTES["l55"]={"Ví dụ: Chu trình trong đồ thị vô hướng": "DFS đi 1 → 2 → 3 → 4 → 5; từ 5 thấy 3 đã thăm và 3 không phải cha của 5 (cha là 4): chu trình 3 – 4 – 5. Cạnh 5 – 4 thì bị bỏ qua vì 4 là cha.", "Ví dụ: Chu trình có hướng bằng ba màu": "Số dưới đỉnh là màu. 1 → 2 → 4 → 5 → 3 rồi 3 → 2: 2 đang xám (dfs(2) chưa xong) nên có chu trình 2 → 4 → 5 → 3 → 2.", "Ví dụ: Tô hai màu bằng BFS": "Đỉnh lẻ của vòng 1 – 2 – 3 – 4 nhận màu 1, đỉnh chẵn màu 2. Chu trình dài 4 (chẵn) không phá được cách tô: đồ thị hai phía, nhóm {1, 3, 5} và {2, 4, 6}.", "Ví dụ: Chu trình lẻ phá cách tô": "Vòng 5 đỉnh (lẻ): đi vòng từ 1, màu đổi 5 lần nên về tới đỉnh kề 1 lại cùng màu với 1. Cạnh 3 – 4 nối hai đỉnh cùng màu 1 khi BFS lan từ hai phía gặp nhau.", "Lỗi: chỉ dùng “đã thăm” cho đồ thị có hướng": "Đồ thị 1 → 2, 1 → 3, 3 → 2 không có chu trình, nhưng chương trình báo có: lúc từ 3 nhìn sang 2, đỉnh 2 đã thăm xong ở nhánh trước (đen), không phải đang trên đường đi (xám). Cần ba màu."};EX_HINTS["l55"]=[["Duyệt (DFS hoặc BFS) và nhớ cha của mỗi đỉnh. Từ u, nếu một đỉnh kề v (khác cha của u) đã được thăm thì có chu trình.", "Đồ thị không có cạnh lặp nên chỉ cần bỏ qua đúng đỉnh cha.", "Cách khác rất gọn: DSU — cạnh nối hai đỉnh đã cùng tập tạo chu trình. Hoặc: mỗi thành phần không có chu trình khi số cạnh = số đỉnh − 1."], ["Đây là kiểm tra đồ thị hai phía. Duyệt s = 1 … n; s chưa tô thì là đỉnh nhỏ nhất của một thành phần mới: tô đội 1.", "BFS: hàng xóm chưa tô nhận đội 3 − đội[u]; hàng xóm đã tô mà cùng đội với u thì không chia được.", "Trong một thành phần liên thông, cách tô bị ép hoàn toàn khi đã chọn màu của một đỉnh."], ["Chỉ đánh dấu “đã thăm” là sai với đồ thị có hướng: gặp lại đỉnh đã xong ở nhánh khác không phải là chu trình.", "Cách 1: DFS ba màu, gặp cạnh tới đỉnh xám là có chu trình. Cách 2 (không đệ quy): thuật toán Kahn, xếp được ít hơn n đỉnh là có chu trình.", "Khuyên u → u cũng là chu trình: Kahn tự xử lý vì bậc vào của u không bao giờ về 0."]];
/* ===================== BÀI 55 · Phát hiện chu trình và đồ thị hai phía ===================== */
/* Bài 55 · Phát hiện chu trình và đồ thị hai phía
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR55=[{label:"Ví dụ: Chu trình trong đồ thị vô hướng",input:"6 6\n1 2\n2 3\n3 4\n4 5\n5 3\n1 6\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\nvector<int> cha;\n\nbool dfs(int u, int p) {               // p: đỉnh cha trên cây DFS\n    tham[u] = true;\n    cha[u] = p;\n    for (int v : adj[u]) {\n        if (v == p) continue;          // cạnh vừa đi tới u, không tính\n        if (tham[v]) return true;      // quay về một đỉnh đã thăm: có chu trình\n        if (dfs(v, u)) return true;\n    }\n    return false;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    tham.assign(n + 1, false);\n    cha.assign(n + 1, 0);\n    bool co = false;\n    for (int u = 1; u <= n && !co; u++)\n        if (!tham[u]) co = dfs(u, 0);\n    cout << (co ? \"co chu trinh\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,mark:"tham",par:"cha",cur:["u","v"]},{type:"calls"}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ntham = [False] * (n + 1)\ncha = [0] * (n + 1)\n\ndef dfs(u, p):                         # p: đỉnh cha trên cây DFS\n    tham[u] = True\n    cha[u] = p\n    for v in adj[u]:\n        if v == p:                     # cạnh vừa đi tới u, không tính\n            continue\n        if tham[v]:                    # quay về một đỉnh đã thăm: có chu trình\n            return True\n        if dfs(v, u):\n            return True\n    return False\n\nco = False\nfor u in range(1, n + 1):\n    if not tham[u] and dfs(u, 0):\n        co = True\n        break\nprint(\"co chu trinh\" if co else \"khong\")"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n    static int[] cha;\n\n    static bool Dfs(int u, int p)          // p: đỉnh cha trên cây DFS\n    {\n        tham[u] = true;\n        cha[u] = p;\n        foreach (int v in adj[u])\n        {\n            if (v == p) continue;          // cạnh vừa đi tới u, không tính\n            if (tham[v]) return true;      // quay về một đỉnh đã thăm: có chu trình\n            if (Dfs(v, u)) return true;\n        }\n        return false;\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        tham = new bool[n + 1];\n        cha = new int[n + 1];\n        bool co = false;\n        for (int u = 1; u <= n && !co; u++)\n            if (!tham[u]) co = Dfs(u, 0);\n        Console.WriteLine(co ? \"co chu trinh\" : \"khong\");\n    }\n}"}},{label:"Ví dụ: Chu trình có hướng bằng ba màu",input:"5 6\n1 2\n1 3\n3 2\n2 4\n4 5\n5 3\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<int> mau;                       // 0 trắng, 1 xám (đang thăm), 2 đen (xong)\n\nbool dfs(int u) {\n    mau[u] = 1;\n    for (int v : adj[u]) {\n        if (mau[v] == 1) return true;  // v đang trên đường đi: khép chu trình\n        if (mau[v] == 0 && dfs(v)) return true;\n    }\n    mau[u] = 2;\n    return false;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n    }\n    mau.assign(n + 1, 0);\n    bool co = false;\n    for (int u = 1; u <= n && !co; u++)\n        if (mau[u] == 0) co = dfs(u);\n    cout << (co ? \"co chu trinh\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",dir:true,lab:"mau",cur:["u","v"]},{type:"calls"}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\nmau = [0] * (n + 1)                    # 0 trắng, 1 xám (đang thăm), 2 đen (xong)\n\ndef dfs(u):\n    mau[u] = 1\n    for v in adj[u]:\n        if mau[v] == 1:                # v đang trên đường đi: khép chu trình\n            return True\n        if mau[v] == 0 and dfs(v):\n            return True\n    mau[u] = 2\n    return False\n\nco = any(mau[u] == 0 and dfs(u) for u in range(1, n + 1))\nprint(\"co chu trinh\" if co else \"khong\")"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static int[] mau;                      // 0 trắng, 1 xám (đang thăm), 2 đen (xong)\n\n    static bool Dfs(int u)\n    {\n        mau[u] = 1;\n        foreach (int v in adj[u])\n        {\n            if (mau[v] == 1) return true;  // v đang trên đường đi: khép chu trình\n            if (mau[v] == 0 && Dfs(v)) return true;\n        }\n        mau[u] = 2;\n        return false;\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n        }\n        mau = new int[n + 1];\n        bool co = false;\n        for (int u = 1; u <= n && !co; u++)\n            if (mau[u] == 0) co = Dfs(u);\n        Console.WriteLine(co ? \"co chu trinh\" : \"khong\");\n    }\n}"}},{label:"Ví dụ: Tô hai màu bằng BFS",input:"6 6\n1 2\n2 3\n3 4\n4 1\n4 5\n5 6\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nvector<vector<int>> adj;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> mau(n + 1, 0);         // 0: chưa tô, 1 hoặc 2\n    bool haiPhia = true;\n    for (int s = 1; s <= n; s++) {\n        if (mau[s] != 0) continue;\n        mau[s] = 1;\n        queue<int> q;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int v : adj[u]) {\n                if (mau[v] == 0) { mau[v] = 3 - mau[u]; q.push(v); }   // màu ngược lại\n                else if (mau[v] == mau[u]) haiPhia = false;           // hai đầu cùng màu\n            }\n        }\n    }\n    cout << (haiPhia ? \"hai phia\" : \"khong\") << \"\\n\";\n    for (int u = 1; u <= n; u++) cout << mau[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"mau",cur:["u","v"]},{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\nmau = [0] * (n + 1)                    # 0: chưa tô, 1 hoặc 2\nhai_phia = True\nfor s in range(1, n + 1):\n    if mau[s]:\n        continue\n    mau[s] = 1\n    q = deque([s])\n    while q:\n        u = q.popleft()\n        for v in adj[u]:\n            if mau[v] == 0:\n                mau[v] = 3 - mau[u]    # màu ngược lại\n                q.append(v)\n            elif mau[v] == mau[u]:     # hai đầu cùng màu\n                hai_phia = False\nprint(\"hai phia\" if hai_phia else \"khong\")\nprint(*mau[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] mau = new int[n + 1];            // 0: chưa tô, 1 hoặc 2\n        bool haiPhia = true;\n        for (int s = 1; s <= n; s++)\n        {\n            if (mau[s] != 0) continue;\n            mau[s] = 1;\n            var q = new Queue<int>();\n            q.Enqueue(s);\n            while (q.Count > 0)\n            {\n                int u = q.Dequeue();\n                foreach (int v in adj[u])\n                {\n                    if (mau[v] == 0) { mau[v] = 3 - mau[u]; q.Enqueue(v); }   // màu ngược lại\n                    else if (mau[v] == mau[u]) haiPhia = false;              // hai đầu cùng màu\n                }\n            }\n        }\n        Console.WriteLine(haiPhia ? \"hai phia\" : \"khong\");\n        for (int u = 1; u <= n; u++) Console.Write(mau[u] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Chu trình lẻ phá cách tô",input:"5 5\n1 2\n2 3\n3 4\n4 5\n5 1\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nvector<vector<int>> adj;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> mau(n + 1, 0);\n    mau[1] = 1;\n    queue<int> q;\n    q.push(1);\n    int xu = 0, xv = 0;\n    while (!q.empty() && xu == 0) {\n        int u = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            if (mau[v] == 0) { mau[v] = 3 - mau[u]; q.push(v); }\n            else if (mau[v] == mau[u]) { xu = u; xv = v; break; }\n        }\n    }\n    if (xu) cout << \"canh \" << xu << \"-\" << xv << \" noi hai dinh cung mau\\n\";\n    else cout << \"hai phia\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"mau",cur:["u","v"]}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\nmau = [0] * (n + 1)\nmau[1] = 1\nq = deque([1])\nxau = None\nwhile q and xau is None:\n    u = q.popleft()\n    for v in adj[u]:\n        if mau[v] == 0:\n            mau[v] = 3 - mau[u]\n            q.append(v)\n        elif mau[v] == mau[u]:\n            xau = (u, v)\n            break\nif xau:\n    print(\"canh \" + str(xau[0]) + \"-\" + str(xau[1]) + \" noi hai dinh cung mau\")\nelse:\n    print(\"hai phia\")"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] mau = new int[n + 1];\n        mau[1] = 1;\n        var q = new Queue<int>();\n        q.Enqueue(1);\n        int xu = 0, xv = 0;\n        while (q.Count > 0 && xu == 0)\n        {\n            int u = q.Dequeue();\n            foreach (int v in adj[u])\n            {\n                if (mau[v] == 0) { mau[v] = 3 - mau[u]; q.Enqueue(v); }\n                else if (mau[v] == mau[u]) { xu = u; xv = v; break; }\n            }\n        }\n        Console.WriteLine(xu != 0 ? \"canh \" + xu + \"-\" + xv + \" noi hai dinh cung mau\" : \"hai phia\");\n    }\n}"}},{label:"Lỗi: chỉ dùng “đã thăm” cho đồ thị có hướng",input:"3 3\n1 2\n1 3\n3 2\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\n\nbool dfs(int u) {\n    tham[u] = true;\n    for (int v : adj[u]) {\n        if (tham[v]) return true;      // SAI: v có thể đã thăm XONG ở nhánh khác\n        if (dfs(v)) return true;\n    }\n    return false;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n    }\n    tham.assign(n + 1, false);\n    cout << (dfs(1) ? \"co chu trinh\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",dir:true,mark:"tham",cur:["u","v"]}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\ntham = [False] * (n + 1)\n\ndef dfs(u):\n    tham[u] = True\n    for v in adj[u]:\n        if tham[v]:                    # SAI: v có thể đã thăm XONG ở nhánh khác\n            return True\n        if dfs(v):\n            return True\n    return False\n\nprint(\"co chu trinh\" if dfs(1) else \"khong\")"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n\n    static bool Dfs(int u)\n    {\n        tham[u] = true;\n        foreach (int v in adj[u])\n        {\n            if (tham[v]) return true;      // SAI: v có thể đã thăm XONG ở nhánh khác\n            if (Dfs(v)) return true;\n        }\n        return false;\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n        }\n        tham = new bool[n + 1];\n        Console.WriteLine(Dfs(1) ? \"co chu trinh\" : \"khong\");\n    }\n}"}}];
